import{_ as r,C as n,o,c as s,a2 as a,b as d,w as t,a as l,E as c,a3 as u}from"./chunks/framework.CgxQ0r6v.js";const E=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_3.md"}'),m={name:"materias/Proyecto_Sociotecnologico_III/documentacion/III-VII/Lectura_Catedra_Evaluacion_3.md"};function p(g,e,f,I,b,C){const i=n("Mermaid");return o(),s("div",null,[e[1]||(e[1]=a('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-vii" tabindex="-1">Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VII) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-iii-trayecto-iii-trimestre-vii" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico III (Trayecto III - Trimestre VII)&quot;">​</a></h2><h3 id="eje-tematico-estudio-de-factibilidad-y-estimacion-de-costos-de-software" tabindex="-1">Eje Temático: Estudio de Factibilidad y Estimación de Costos de Software <a class="header-anchor" href="#eje-tematico-estudio-de-factibilidad-y-estimacion-de-costos-de-software" aria-label="Permalink to &quot;Eje Temático: Estudio de Factibilidad y Estimación de Costos de Software&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-economia-y-viabilidad-de-la-ingenieria-de-software" tabindex="-1">🧭 Introducción: La Economía y Viabilidad de la Ingeniería de Software <a class="header-anchor" href="#🧭-introduccion-la-economia-y-viabilidad-de-la-ingenieria-de-software" aria-label="Permalink to &quot;🧭 Introducción: La Economía y Viabilidad de la Ingeniería de Software&quot;">​</a></h2><p>En el nivel de Trayecto III, los estudiantes no solo deben demostrar que saben programar; deben demostrar que comprenden <strong>la dimensión económica, técnica y gerencial de un proyecto de software</strong>.</p><p>¿Cuánto esfuerzo humano requiere construir el sistema? ¿Cuántos meses tomará el desarrollo? ¿Cuál sería el costo comercial de esta aplicación si la institución tuviera que contratar una empresa privada? ¿Cuánto dinero público ahorra la universidad y la comunidad gracias a la adopción de Software Libre? Responder estas preguntas con modelos matemáticos reconocidos internacionalmente es una exigencia académica del PST III.</p><hr><h2 id="🔬-capitulo-i-las-cuatro-dimensiones-de-factibilidad-en-pst-iii" tabindex="-1">🔬 CAPÍTULO I: Las Cuatro Dimensiones de Factibilidad en PST III <a class="header-anchor" href="#🔬-capitulo-i-las-cuatro-dimensiones-de-factibilidad-en-pst-iii" aria-label="Permalink to &quot;🔬 CAPÍTULO I: Las Cuatro Dimensiones de Factibilidad en PST III&quot;">​</a></h2>',9)),(o(),d(u,null,{default:t(()=>[c(i,{id:"mermaid-23",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20F%5B%22%F0%9F%94%8D%20Estudio%20de%20Factibilidad%20en%20PST%20III%22%5D%0A%20%20%20%20F%20--%3E%20FT%5B%22%F0%9F%92%BB%20Factibilidad%20T%C3%A9cnica%3A%20Servidores%2C%20redes%20LAN%2FWAN%2C%20SGBD%20concurrente%22%5D%0A%20%20%20%20F%20--%3E%20FO%5B%22%F0%9F%91%A5%20Factibilidad%20Operativa%3A%20Cultura%20organizacional%2C%20capacitaci%C3%B3n%2C%20adopci%C3%B3n%22%5D%0A%20%20%20%20F%20--%3E%20FE%5B%22%F0%9F%92%B0%20Factibilidad%20Econ%C3%B3mica%3A%20Estimaci%C3%B3n%20formal%20de%20esfuerzo%20(COCOMO%20%2F%20PF)%22%5D%0A%20%20%20%20F%20--%3E%20FL%5B%22%E2%9A%96%EF%B8%8F%20Factibilidad%20Legal%3A%20Ley%20de%20Infogobierno%2C%20Soberan%C3%ADa%20y%20Licencia%20GPL%20v3%22%5D%0A%0A%20%20%20%20style%20F%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20FT%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20FO%20fill%3A%230f766e%2Cstroke%3A%2314b8a6%2Ccolor%3A%23fff%0A%20%20%20%20style%20FE%20fill%3A%23b45309%2Cstroke%3A%23f59e0b%2Ccolor%3A%23fff%0A%20%20%20%20style%20FL%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="📐-capitulo-ii-modelos-de-estimacion-de-esfuerzo-y-costos-de-software" tabindex="-1">📐 CAPÍTULO II: Modelos de Estimación de Esfuerzo y Costos de Software <a class="header-anchor" href="#📐-capitulo-ii-modelos-de-estimacion-de-esfuerzo-y-costos-de-software" aria-label="Permalink to &quot;📐 CAPÍTULO II: Modelos de Estimación de Esfuerzo y Costos de Software&quot;">​</a></h2><p>Estimar software a &quot;ojo de buen cubero&quot; es inaceptable en ingeniería. Existen dos modelos universales fundamentales:</p><h3 id="_2-1-metodo-de-puntos-de-funcion-function-points-ifpug" tabindex="-1">2.1 Método de Puntos de Función (Function Points - IFPUG) <a class="header-anchor" href="#_2-1-metodo-de-puntos-de-funcion-function-points-ifpug" aria-label="Permalink to &quot;2.1 Método de Puntos de Función (Function Points - IFPUG)&quot;">​</a></h3><p>Mide el tamaño del software en función de la funcionalidad que entrega al usuario, independiente del lenguaje de programación. Evalúa cinco componentes:</p><ol><li><strong>Entradas Externas (EI):</strong> Formularios que introducen o modifican datos (ej: registrar usuario).</li><li><strong>Salidas Externas (EO):</strong> Reportes generados que procesan y calculan datos (ej: constancia con código QR).</li><li><strong>Consultas Externas (EQ):</strong> Búsquedas en pantalla sin cálculos complejos.</li><li><strong>Archivos Lógicos Internos (ILF):</strong> Grupos de datos mantenidos dentro del sistema (las tablas principales de la base de datos).</li><li><strong>Archivos de Interfaz Externa (EIF):</strong> Datos consultados de otros sistemas externos.</li></ol><h3 id="_2-2-el-modelo-cocomo-basico-constructive-cost-model-barry-boehm" tabindex="-1">2.2 El Modelo COCOMO Básico (Constructive Cost Model - Barry Boehm) <a class="header-anchor" href="#_2-2-el-modelo-cocomo-basico-constructive-cost-model-barry-boehm" aria-label="Permalink to &quot;2.2 El Modelo COCOMO Básico (Constructive Cost Model - Barry Boehm)&quot;">​</a></h3><p>Permite calcular el esfuerzo en <strong>personas-mes (PM)</strong> y el <strong>tiempo de desarrollo (TDEV)</strong> a partir de las miles de líneas de código fuente estimadas (KLOC):</p><p>$$\\text{Esfuerzo (PM)} = a \\times (\\text{KLOC})^b$$ $$\\text{Tiempo (TDEV)} = c \\times (\\text{Esfuerzo})^d$$</p><p>Para proyectos típicos de software comunitario (Modo Orgánico):</p><ul><li>Constantes: $a = 2.4$, $b = 1.05$, $c = 2.5$, $d = 0.38$.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Ejemplo de Cálculo COCOMO en PST III:</strong> Si un sistema se estima en 10.000 líneas de código (10 KLOC): $$\\text{Esfuerzo} = 2.4 \\times (10)^{1.05} \\approx 26.9 \\text{ personas-mes}$$ $$\\text{Tiempo} = 2.5 \\times (26.9)^{0.38} \\approx 8.7 \\text{ meses}$$ Esto demuestra que un equipo de 3 estudiantes trabajando durante un año académico (9 meses) es la dimensión exacta requerida para culminar el proyecto con éxito.</p></div><hr><h2 id="💵-capitulo-iii-analisis-de-costo-total-de-propiedad-tco-y-ahorro-por-software-libre" tabindex="-1">💵 CAPÍTULO III: Análisis de Costo Total de Propiedad (TCO) y Ahorro por Software Libre <a class="header-anchor" href="#💵-capitulo-iii-analisis-de-costo-total-de-propiedad-tco-y-ahorro-por-software-libre" aria-label="Permalink to &quot;💵 CAPÍTULO III: Análisis de Costo Total de Propiedad (TCO) y Ahorro por Software Libre&quot;">​</a></h2><p>El equipo debe calcular el <strong>Costo Total de Propiedad (TCO)</strong>, comparando el escenario privativo vs. el escenario libre:</p><table tabindex="0"><thead><tr><th>Rubro de Inversión</th><th style="text-align:center;">Solución Comercial Privada (USD)</th><th style="text-align:center;">Solución Libre con el PNFI / UPTT</th></tr></thead><tbody><tr><td>Licencias de Sistema Operativo Servidor (Windows Server)</td><td style="text-align:center;">$ 1.200</td><td style="text-align:center;"><strong>$ 0 (Debian / Rocky Linux)</strong></td></tr><tr><td>Licencias de Base de Datos (Oracle / MS SQL Server)</td><td style="text-align:center;">$ 3.500</td><td style="text-align:center;"><strong>$ 0 (PostgreSQL / MariaDB)</strong></td></tr><tr><td>Licencias de Servidor Web y Entorno de Desarrollo</td><td style="text-align:center;">$ 800</td><td style="text-align:center;"><strong>$ 0 (Apache / Nginx / FOSS)</strong></td></tr><tr><td>Costo de Licencia por Puesto de Trabajo (CALs)</td><td style="text-align:center;">$ 1.500</td><td style="text-align:center;"><strong>$ 0 (Acceso Web Ilimitado)</strong></td></tr><tr><td>Desarrollo a Medida del Software</td><td style="text-align:center;">$ 6.000</td><td style="text-align:center;"><strong>$ 0 (Aporte Social Comunitario)</strong></td></tr><tr><td><strong>TOTAL INVERSIÓN:</strong></td><td style="text-align:center;"><strong>$ 13.000</strong></td><td style="text-align:center;"><strong>$ 0</strong></td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>El Aporte Social del Estudiante:</strong> El cuadro anterior debe incluirse en el Capítulo I o III del informe, demostrando cómo el proyecto universitario ahorra miles de dólares al Estado o a la comunidad, cumpliendo con la premisa de soberanía e independencia económica.</p></div><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-3" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 3 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-3" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 3&quot;">​</a></h2><p>Para la Evaluación 3 del Trimestre VII:</p><ol><li><strong>Estudio de Factibilidad Cuadridimensional:</strong> Con inventario técnico y marco legal de Software Libre.</li><li><strong>Cálculo de Estimación de Esfuerzo y Costos:</strong> Aplicando Puntos de Función o COCOMO Básico.</li><li><strong>Cuadro Comparativo de Ahorro Tecnológico (TCO):</strong> Demostración del impacto económico para la comunidad.</li></ol>',21))])}const y=r(m,[["render",p]]);export{E as __pageData,y as default};
